    fun `openUploadReader`(`uploadId`: kotlin.String): kotlin.String
    
    fun `paper`(`projectId`: kotlin.String, `paperId`: kotlin.String): kotlin.String
    
    /**
     * Durable review preparation. No business grant, pending row or effect is created.
     * The native plan, exact raw parameters and intent remain stable for review.
     */
    fun `prepare`(`operationJson`: kotlin.String, `projectId`: kotlin.String?, `expectedRevision`: kotlin.String): kotlin.String
    
    fun `readAttachment`(`readerId`: kotlin.String, `maxBytes`: kotlin.UInt): kotlin.ByteArray
    
    fun `researchSources`(`projectId`: kotlin.String): kotlin.String
    
    /**
     * Only upload ids created by the trusted file host are accepted. Contents
     * are re-read and validated in Rust, never supplied as a model manifest.
     */
    fun `sealSnapshot`(`projectId`: kotlin.String, `entriesJson`: kotlin.String, `archiveUploadId`: kotlin.String?): kotlin.String
    
    fun `supplier`(`supplierId`: kotlin.String): kotlin.String
    
    companion object
}

open class ProductCore: Disposable, AutoCloseable, ProductCoreInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_muyon_android_product_fn_free_productcore(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_muyon_android_product_fn_clone_productcore(handle, status)
        }
    }

    
    @Throws(ProductException::class)override fun `abortUpload`(`uploadId`: kotlin.String)
        = 
    callWithHandle {
    uniffiRustCallWithError(ProductException) { _status ->
    UniffiLib.uniffi_muyon_android_product_fn_method_productcore_abort_upload(
        it,
        
        FfiConverterString.lower(`uploadId`),_status)
}
    }
    
    

    override fun `agentAllowed`(`request`: kotlin.String, `configuration`: kotlin.String, `generation`: kotlin.String): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_muyon_android_product_fn_method_productcore_agent_allowed(
        it,
        
        FfiConverterString.lower(`request`),
        FfiConverterString.lower(`configuration`),
        FfiConverterString.lower(`generation`),_status)
}
    }
    )
    }
    

    
    @Throws(ProductException::class)override fun `agentAvailability`(): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCallWithError(ProductException) { _status ->
    UniffiLib.uniffi_muyon_android_product_fn_method_productcore_agent_availability(
        it,
        _status)
}
    }
    )
    }
    

    
    @Throws(ProductException::class)override fun `agentBudget`(): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCallWithError(ProductException) { _status ->
    UniffiLib.uniffi_muyon_android_product_fn_method_productcore_agent_budget(
        it,
        _status)
}
    }
    )
    }
    

    
    @Throws(ProductException::class)override fun `agentCancel`(`request`: kotlin.String): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCallWithError(ProductException) { _status ->
