        it,
        
        FfiConverterString.lower(`request`),_status)
}
    }
    )
    }
    

    
    /**
     * Private transport port. Never registered as a UI/model operation.
     */
    @Throws(ProductException::class)override fun `agentClaim`(`request`: kotlin.String, `configuration`: kotlin.String, `generation`: kotlin.String): kotlin.String {
            return FfiConverterString.lift(
