    /**
     * HOST ONLY: visible settings confirmation; no credential bytes cross FFI.
     */
    @Throws(ProductException::class)override fun `agentConfigure`(`settingsJson`: kotlin.String): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCallWithError(ProductException) { _status ->
