sealed class ProductException: kotlin.Exception() {
    
    class Failure(
        
        val `code`: kotlin.String
        ) : ProductException() {
        override val message
            get() = "code=${ `code` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ProductException> {
        override fun lift(error_buf: RustBuffer.ByValue): ProductException = FfiConverterTypeProductError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeProductError : FfiConverterRustBuffer<ProductException> {
    override fun read(buf: ByteBuffer): ProductException {
        

        return when(buf.getInt()) {
            1 -> ProductException.Failure(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ProductException): ULong {
        return when(value) {
            is ProductException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
            )
        }
    }

    override fun write(value: ProductException, buf: ByteBuffer) {
        when(value) {
            is ProductException.Failure -> {
                buf.putInt(1)
                FfiConverterString.write(value.`code`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUShort: FfiConverterRustBuffer<kotlin.UShort?> {
    override fun read(buf: ByteBuffer): kotlin.UShort? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUShort.read(buf)
    }

    override fun allocationSize(value: kotlin.UShort?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUShort.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UShort?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUShort.write(value, buf)
        }
    }
}




